  "check_code": "import json
import sqlite3
from pathlib import Path


TARGET_IDS = (
    "RP-2025-0929-0177-0003",
    "RP-2025-0930-0177-0004",
    "RP-2025-0930-0177-0005",
)


def _db_path(workspace):
    workspace = Path(workspace)
    return workspace.parent / "system" / "bofa_cashpro" / "state.db"


def _backup_path(workspace):
    workspace = Path(workspace)
    return workspace.parent / "system" / "bofa_cashpro" / "state.db.pinned_backup"


def _connect(path):
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def check_target_posting_statuses(workspace):
    expected = {
        "RP-2025-0929-0177-0003": "APPLIED",
        "RP-2025-0930-0177-0004": "REVERSED",
        "RP-2025-0930-0177-0005": "REVERSED",
    }
    with _connect(_db_path(workspace)) as con:
        rows = con.execute(
            "SELECT posting_id, application_status FROM receipt_postings WHERE posting_id IN (?,?,?)",
            TARGET_IDS,
        ).fetchall()
    actual = {row["posting_id"]: row["application_status"] for row in rows}
    ok = actual == expected
    return {"score": 1 if ok else 0, "detail": f"expected={expected}; actual={actual}"}


def check_duplicate_review_audit_entries(workspace):
    expected_new = {
        "RP-2025-0929-0177-0003": ("APPLIED", "valid_receipt"),
        "RP-2025-0930-0177-0004": ("REVERSED", "confirmed_duplicate"),
        "RP-2025-0930-0177-0005": ("REVERSED", "confirmed_duplicate"),
    }
    db = _db_path(workspace)
    with _connect(db) as con:
        table = con.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='implementation_audit_log'"
        ).fetchone()
        if table is None:
            return {"score": 0, "detail": "implementation_audit_log does not exist"}
        rows = con.execute(
            "SELECT action_type, posting_id, old_value, new_value, disposition, audit_note, operator_identity "
            "FROM implementation_audit_log WHERE action_type='DUPLICATE_REVIEW' AND posting_id IN (?,?,?) "
            "ORDER BY audit_id",
            TARGET_IDS,
        ).fetchall()
    actual = [(row["posting_id"], row["new_value"], row["disposition"]) for row in rows]
    unique_ids = {row["posting_id"] for row in rows}
    details_ok = all(
        row["action_type"] == "DUPLICATE_REVIEW"
        and row["old_value"] == "DUPLICATE_REVIEW"
        and row["audit_note"].strip()
        and row["operator_identity"].strip() == "Ethan Brooks"
        and expected_new.get(row["posting_id"]) == (row["new_value"], row["disposition"])
        for row in rows
    )
    ok = len(rows) == 3 and len(unique_ids) == 3 and details_ok
    return {"score": 1 if ok else 0, "detail": json.dumps({"actual": actual, "count": len(rows)})}


def check_unrelated_postings_unchanged(workspace):
    """Compare the pinned audit-sample rows that are outside the target cluster."""
    with _connect(_db_path(workspace)) as con:
        current_rows = con.execute("SELECT * FROM receipt_postings ORDER BY posting_id").fetchall()
    with _connect(_backup_path(workspace)) as con:
        baseline_rows = con.execute("SELECT * FROM receipt_postings ORDER BY posting_id").fetchall()
    baseline = {
        row["posting_id"]: tuple(row)
        for row in baseline_rows
        if row["posting_id"] not in TARGET_IDS
    }
    current = {row["posting_id"]: tuple(row) for row in current_rows}
    ok = all(current.get(posting_id) == row for posting_id, row in baseline.items())
    return {"score": 1 if ok else 0, "detail": f"pinned_unrelated_rows_match={ok}; checked={len(baseline)}"}
